import javax.net.ssl.*;import java.io.*;import java.net.*;import java.nio.charset.StandardCharsets;import java.nio.file.*;import java.security.*;import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.*;
public class HandshakeProbe {
 static String enc(String v){return Base64.getUrlEncoder().withoutPadding().encodeToString(v.getBytes(StandardCharsets.UTF_8));}
 public static void main(String[] a)throws Exception {
  char[] pw="synthetic".toCharArray();KeyStore ks=KeyStore.getInstance("PKCS12");try(InputStream in=Files.newInputStream(Path.of("/test/server.p12"))){ks.load(in,pw);}KeyManagerFactory km=KeyManagerFactory.getInstance(KeyManagerFactory.getDefaultAlgorithm());km.init(ks,pw);SSLContext ctx=SSLContext.getInstance("TLS");ctx.init(km.getKeyManagers(),null,null);
  SSLServerSocket server=(SSLServerSocket)ctx.getServerSocketFactory().createServerSocket(0,32,InetAddress.getByName("127.0.0.1"));server.setSoTimeout(300);
  AtomicBoolean stop=new AtomicBoolean(),wsSeen=new AtomicBoolean(),wsAccepted=new AtomicBoolean(),httpSeen=new AtomicBoolean();ExecutorService pool=Executors.newCachedThreadPool();
  Thread accept=new Thread(()->{while(!stop.get())try{SSLSocket sock=(SSLSocket)server.accept();pool.submit(()->{try{sock.setSoTimeout(10000);BufferedReader r=new BufferedReader(new InputStreamReader(sock.getInputStream(),StandardCharsets.US_ASCII));String first=r.readLine();if(first==null)return;Map<String,String> h=new HashMap<>();String line;while((line=r.readLine())!=null&&!line.isEmpty()){int i=line.indexOf(':');if(i>0)h.put(line.substring(0,i).toLowerCase(Locale.ROOT),line.substring(i+1).trim());}OutputStream out=sock.getOutputStream();if("websocket".equalsIgnoreCase(h.get("upgrade"))){wsSeen.set(true);String key=h.get("sec-websocket-key");String acceptKey=Base64.getEncoder().encodeToString(MessageDigest.getInstance("SHA-1").digest((key+"258EAFA5-E914-47DA-95CA-C5AB0DC85B11").getBytes(StandardCharsets.US_ASCII)));out.write(("HTTP/1.1 101 Switching Protocols\r\nUpgrade: websocket\r\nConnection: Upgrade\r\nSec-WebSocket-Accept: "+acceptKey+"\r\nSec-WebSocket-Protocol: v1.notify\r\n\r\n").getBytes(StandardCharsets.US_ASCII));out.flush();wsAccepted.set(true);Thread.sleep(3500);}else{if(first.contains("/manager/device/topologies"))httpSeen.set(true);byte[] body="{\"code\":0,\"data\":{\"pagination\":{\"page_num\":1,\"page_size\":1000,\"total\":0},\"list\":[]}}".getBytes(StandardCharsets.US_ASCII);out.write(("HTTP/1.1 200 OK\r\nContent-Type: application/json\r\nContent-Length: "+body.length+"\r\nConnection: close\r\n\r\n").getBytes(StandardCharsets.US_ASCII));out.write(body);out.flush();}}catch(Exception ignored){}finally{try{sock.close();}catch(Exception ignored){}}});}catch(SocketTimeoutException ignored){}catch(Exception ignored){break;}});accept.start();
  ProcessBuilder pb=new ProcessBuilder("java","-cp","/test/out:/sdk/flight-hub-sdk-patched.jar","DjiCloud2Bridge");pb.redirectError(ProcessBuilder.Redirect.DISCARD);Process p=pb.start();OutputStream w=p.getOutputStream();String h=enc("X-Workspace-Token"),secret=enc("synthetic-test-secret");w.write(("INIT\t1\t"+enc("127.0.0.1")+"\t"+server.getLocalPort()+"\t1\t"+h+"\t"+secret+"\t1\t"+h+"\t"+secret+"\nLIST\t77fb733a-7dc0-4a94-9bc3-756f487bf854\n").getBytes(StandardCharsets.US_ASCII));w.flush();Thread.sleep(4000);try{w.write("CLOSE\n".getBytes());w.close();}catch(Exception ignored){}boolean done=p.waitFor(20,TimeUnit.SECONDS);if(!done)p.destroyForcibly();String output=new String(p.getInputStream().readAllBytes(),StandardCharsets.US_ASCII);stop.set(true);server.close();accept.join();pool.shutdownNow();pool.awaitTermination(5,TimeUnit.SECONDS);
  String logs="";try(java.util.stream.Stream<Path> paths=Files.walk(Path.of("/test"))){for(Path x:paths.filter(Files::isRegularFile).filter(z->z.toString().endsWith(".log")).toList())logs+=Files.readString(x);}String encoded=enc("X-Workspace-Token=synthetic-test-secret");
  System.out.println("http_seen="+httpSeen.get()+" http_result="+output.contains("RESULT\t")+" wss_request="+wsSeen.get()+" wss_101_sent="+wsAccepted.get()+" native_ws_established="+logs.contains("LWS_CALLBACK_CLIENT_ESTABLISHED")+" secret_plain_logged="+logs.contains("synthetic-test-secret")+" secret_encoded_logged="+(logs.contains(encoded)||logs.contains(enc("synthetic-test-secret")))+" secret_in_stdout="+(output.contains("synthetic-test-secret")||output.contains(encoded))+" timeout="+!done);
 }
}
